class SetRouteRulesRequestRouteRule(ScalewayModel):
    rule_http_match: RuleHttpMatch | None = None
    """
    Rule condition to be matched. Requests matching the condition defined here will be
    directly forwarded to the backend specified by the `backend_stage_id` or
    `waf_stage_id` fields. Requests that do not match will be checked by the next rule's
    condition.
    Precisely one of rule_http_match can be set.
    """
    backend_stage_id: str | None = None
    """
    ID of the backend stage that requests matching the rule should be forwarded to.
    (UUID format)
    Precisely one of backend_stage_id, waf_stage_id can be set.
    """
    waf_stage_id: str | None = None
    """
    ID of the WAF stage that requests matching the rule should be forwarded to. (UUID
    format)
    Precisely one of backend_stage_id, waf_stage_id can be set.
    """


class SetRouteRulesResponse(ScalewayModel):
    route_rules: list[RouteRule] = Field(default_factory=list)
    """
    List of rules to be checked against every HTTP request. The first matching rule will
    forward the request to its specified backend stage. If no rules are matched, the
    request is forwarded to the stage defined by `waf_stage_id` or `backend_stage_id`.
    """


class TLSSecret(ScalewayModel):
    secret_id: str
    """
    ID of the Secret.
    """
    region: str
    """
    Region of the Secret.
    """


class TLSSecretsConfig(ScalewayModel):
    tls_secrets: list[TLSSecret] = Field(default_factory=list)
    """
    Secret information (from Secret Manager).
    """


class TLSStage(ScalewayModel):
    id: str = ""
    """
    ID of the TLS stage.
    """
    secrets: list[TLSSecret] = Field(default_factory=list)
    """
    Secret (from Scaleway Secret Manager) containing your custom certificate.
    """
    managed_certificate: bool = False
    """
    True when Scaleway generates and manages a Let's Encrypt certificate for the TLS
    stage/custom endpoint.
    """
    pipeline_id: str = ""
    """
    Pipeline ID the TLS stage belongs to.
    """
    certificate_expires_at: datetime | None = None
    """
    Expiration date of the certificate. (RFC 3339 format)
    """
    status: StageStatus = StageStatus("unknown_status")
    """
    Current status of the stage.
    """
    created_at: datetime | None = None
    """
    Date the TLS stage was created. (RFC 3339 format)
    """
    updated_at: datetime | None = None
    """
    Date the TLS stage was last updated. (RFC 3339 format)
    """
    cache_stage_id: str | None = None
    """
    Cache stage ID the TLS stage is linked to. (UUID format)
    Precisely one of cache_stage_id, backend_stage_id, waf_stage_id, route_stage_id can
    be set.
    """
    backend_stage_id: str | None = None
    """
    Backend stage ID the TLS stage is linked to. (UUID format)
    Precisely one of cache_stage_id, backend_stage_id, waf_stage_id, route_stage_id can
    be set.
    """
    waf_stage_id: str | None = None
    """
    (UUID format)
    Precisely one of cache_stage_id, backend_stage_id, waf_stage_id, route_stage_id can
    be set.
    """
    route_stage_id: str | None = None
    """
    (UUID format)
    Precisely one of cache_stage_id, backend_stage_id, waf_stage_id, route_stage_id can
    be set.
    """


class WafExclusionRule(ScalewayModel):
    rule_id: int = 0


class WafExclusionRules(ScalewayModel):
    rules: list[WafExclusionRule] = Field(default_factory=list)


class WafStage(ScalewayModel):
    id: str = ""
    """
    ID of the WAF stage.
    """
    pipeline_id: str = ""
    """
    Pipeline ID the WAF stage belongs to.
    """
    mode: WafStageMode = WafStageMode("unknown_mode")
    """
    Mode defining WAF behavior (`disable`/`log_only`/`enable`).
    """
    paranoia_level: int = 0
    """
    Sensitivity level (`1`,`2`,`3`,`4`) to use when classifying requests as malicious.
    With a high level, requests are more likely to be classed as malicious, and false
    positives are expected. With a lower level, requests are more likely to be classed
    as benign.
    """
    status: StageStatus = StageStatus("unknown_status")
    """
    Current status of the stage.
    """
    created_at: datetime | None = None
    """
    Date the WAF stage was created. (RFC 3339 format)
    """
    updated_at: datetime | None = None
    """
    Date the WAF stage was last updated. (RFC 3339 format)
    """
    backend_stage_id: str | None = None
    """
    ID of the backend stage to forward requests to after the WAF stage. (UUID format)
    Precisely one of backend_stage_id can be set.
    """
    exclusion_rules: list[WafExclusionRule] = Field(default_factory=list)
    """
    List of OWASP® CRS rule IDs excluded from WAF.
    """
